shell_commands:
node -e "
for (const [label, mod] of [['ajv6', './node_modules/eslint/node_modules/ajv'], ['ajv8', 'ajv']]) {
  const loaded = require(mod);
  const Ctor = loaded.default || loaded;
  const ajv = new Ctor({strict: false, validateFormats: false});
  console.log('===', label, '===');
  try {
    ajv.compile({type: 'object', properties: {x: {type: 'not-a-type'}}});
    console.log('bad schema DID NOT THROW');
  } catch (e) {
    console.log('bad schema threw:', e.message);
  }
  const v = ajv.compile({
    type: 'object',
    properties: {
      location: {type: 'string'},
      unit: {type: 'string', enum: ['c', 'f']},
      nested: {type: 'object', properties: {code: {type: 'string'}}, required: ['code']}
    },
    required: ['location']
  });
  v({}); console.log('missing root:', v.errors);
  v({location: 123}); console.log('wrong type:', v.errors);
  v({location: 'Paris', unit: 'k'}); console.log('bad enum:', v.errors);
  v({location: 'Paris', nested: {}}); console.log('missing nested:', v.errors);
  v({location: 'Paris', nested: {code: 42}}); console.log('wrong nested type:', v.errors);
  const extra = {location: 'Paris', extra: 99};
  console.log('extra valid:', v(extra), extra);
}
"
